function ChatRoom({ roomId }) {
  const [messages, setMessages] = useState([]);

  useEffect(() => {
    const conn = createConnection(roomId);
    conn.on("message", (m) => {
      setMessages((prev) => [...prev, m]);
    });
    conn.connect();
    return () => conn.disconnect();
  }, []);

  return <MessageList items={messages} />;
}

